function specialization_matrix(carrier, opens):
    for each a in carrier:
        U_a <- carrier
        for each U in opens with a in U:
            U_a <- U_a intersect U          # minimal open nbhd of a
    for each a in carrier:
        for each b in carrier:
            S[b][a] <- (b in U_a)            # b ~> a
    return S

