    opens <- empty set
    for each subset s of carrier:
        down_closed <- true
        for each pair (b, a) in rel:
            if a in s and b not in s:
                down_closed <- false; break
        if down_closed: add s to opens
    return opens

function topologies_equal(carrier, opens1, opens2):
    return specialization_matrix(carrier, opens1)
         == specialization_matrix(carrier, opens2)   # sound & complete (Thm 3)

